#!/usr/bin/env python3
"""
================================================================================
Amazon ML Challenge 2026 — LightGBM Entity Matcher Pipeline (Kaggle Edition)
================================================================================
Architecture:
  - Multi-Channel Inverted Index Blocking Engine
  - Pairwise 12-Dimensional Feature Vector Construction
  - Trained LightGBM Gradient Boosted Decision Tree Matcher
  - Calibrated Decision Thresholding (tau = 0.980) for Macro-F0.5
  - Outputs matching_results.tsv and candidate_pairs.tsv to /kaggle/working/
================================================================================
"""

import os
import sys
import gc
import re
import time
import gzip
import base64
import shutil
from collections import defaultdict
import subprocess

print("=" * 80)
print(" Amazon ML Challenge 2026 — LightGBM Entity Matcher Pipeline (Kaggle)")
print("=" * 80, flush=True)

# 1. Install & Import Dependencies
for pkg in ["rapidfuzz", "polars", "lightgbm", "joblib"]:
    try:
        __import__(pkg.replace("-", "_"))
    except ImportError:
        print(f"[*] Installing {pkg}...", flush=True)
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", pkg], check=False)

import polars as pl
from rapidfuzz import fuzz
import joblib
import numpy as np

# Hardware Check
try:
    import torch
    if torch.cuda.is_available():
        print(f"[+] GPU Active: {torch.cuda.get_device_name(0)}", flush=True)
    else:
        print("[+] CPU Multi-Core Engine Active", flush=True)
except Exception:
    pass

# 2. Decode & Load Trained LightGBM Model
print("[*] Loading trained LightGBM Entity Matcher model...", flush=True)
MODEL_B64 = ""
raw_bytes = gzip.decompress(base64.b64decode(MODEL_B64.encode("ascii")))
os.makedirs("/kaggle/working/model", exist_ok=True)
model_path = "/kaggle/working/model/lgbm_entity_matcher.joblib"
with open(model_path, "wb") as f:
    f.write(raw_bytes)

clf = joblib.load(model_path)
TAU = 0.980
print(f"[+] LightGBM model loaded (300 trees). Calibrated threshold tau = {TAU:.3f}", flush=True)

# 3. Locate Dataset
test_dir = None
search_candidates = [
    "/kaggle/input/amazon-ml-dataset/student_resource/student_resource/dataset/test",
    "/kaggle/input/amazon-ml-dataset/student_resource/dataset/test",
    "/kaggle/input/amazon-ml-dataset/dataset/test",
    "/kaggle/input/dataset/test",
    "dataset/test",
    "student_resource/dataset/test",
]

for cand in search_candidates:
    if os.path.exists(os.path.join(cand, "test_source1.tsv")):
        test_dir = cand
        break

if test_dir is None:
    for root, _, files in os.walk("/kaggle/input"):
        if "test_source1.tsv" in files:
            test_dir = root
            break

print(f"[+] Test Directory Located: {test_dir}", flush=True)

s1_path = os.path.join(test_dir, "test_source1.tsv")
s2_path = os.path.join(test_dir, "test_source2.tsv")
s3_path = os.path.join(test_dir, "test_source3.tsv")

# Normalization Lookups
_COUNTRY_MAP = {
    "usa": "us", "united states": "us", "uk": "gb",
    "united kingdom": "gb", "great britain": "gb",
    "deutschland": "de", "germany": "de", "france": "fr",
    "italia": "it", "italy": "it", "espana": "es", "spain": "es",
    "india": "in", "china": "cn", "japan": "jp", "canada": "ca",
    "australia": "au", "brazil": "br", "brasil": "br", "mexico": "mx",
}

LEGAL_SUFFIXES = {
    "ltd", "limited", "inc", "incorporated", "corp", "corporation",
    "llc", "gmbh", "sa", "sarl", "sas", "sasu", "eurl", "sci", "snc", "scop", "ei",
    "sl", "bv", "co", "company", "pvt", "private", "plc", "srl", "pty",
    "holdings", "group", "mr", "mrs", "dr", "dds", "services", "service",
    "center", "centre", "solutions", "enterprises", "enterprise", "partners",
    "consulting", "associates", "llp", "public", "pllc", "pc", "pa",
    "traders", "agency", "agencies", "stores",
}

_ADDR_COMMON = {
    "rd": "road", "st": "street", "ave": "avenue", "av": "avenue",
    "blvd": "boulevard", "dr": "drive", "ln": "lane", "ct": "court",
    "sq": "square", "ste": "suite", "apt": "apartment", "dept": "department",
    "fl": "floor", "bldg": "building", "hwy": "highway", "pkwy": "parkway",
    "str": "strasse", "pl": "place", "terr": "terrace",
    "cir": "circle", "trl": "trail", "twp": "township",
    "bd": "boulevard", "bvd": "boulevard", "ch": "chemin",
    "imp": "impasse", "rte": "route", "crs": "cours", "al": "allee",
    "fg": "faubourg", "pass": "passage", "qu": "quai",
    "1st": "first", "2nd": "second", "3rd": "third", "4th": "fourth",
    "5th": "fifth", "6th": "sixth", "7th": "seventh", "8th": "eighth",
    "9th": "ninth", "10th": "tenth",
}

def norm_country(c):
    if not c or c != c:
        return ""
    c_clean = str(c).strip().lower()
    return _COUNTRY_MAP.get(c_clean, c_clean)

def clean_name(name):
    if not name or name != name:
        return ""
    s = str(name).lower()
    s = re.sub(r"\([^)]*\)", "", s)
    s = re.sub(r"https?://\S+|www\.\S+|\.(?:com|org|net|in|fr|co|io|biz|info|gov)\b", "", s)
    s = re.sub(r"[-–—]\s*\d{6,}\b", "", s)
    s = re.sub(r"#\s*\d+\b", "", s)
    s = re.sub(r"[^\w\s]", " ", s)
    return " ".join(s.split())

def core_name(cleaned_name):
    if not cleaned_name:
        return ""
    words = cleaned_name.split()
    filtered = [w for w in words if w not in LEGAL_SUFFIXES]
    return " ".join(filtered) if filtered else cleaned_name

def name_no_space(cleaned_name):
    if not cleaned_name:
        return ""
    return re.sub(r"\s+", "", cleaned_name)

def clean_addr(addr, country):
    if not addr or addr != addr:
        return ""
    s = str(addr).lower()
    s = re.sub(r"\b(?:null|none|nan|n\s*/\s*a|<null>)\b", " ", s)
    s = re.sub(r"[^\w\s/]", " ", s)
    tokens = s.split()
    expanded = [_ADDR_COMMON.get(t, t) for t in tokens]
    return " ".join(expanded)

def extract_addr_features(raw_addr, clean_a, country):
    postal = ""
    if country == "us":
        m = re.findall(r"\b(\d{5})(?:-\d{4})?\b", str(raw_addr))
        if m:
            postal = m[-1]
    elif country == "in":
        m = re.findall(r"\b([1-9]\d{5})\b", str(raw_addr))
        if m:
            postal = m[-1]
    elif country == "fr":
        m = re.findall(r"\b(\d{5})\b", str(raw_addr))
        if m:
            postal = m[-1]

    nums = re.findall(r"\b\d+\b", clean_a)
    hnum = nums[0] if nums else ""
    nums_set = set(nums)
    street_words = [w for w in clean_a.split() if len(w) >= 4 and not w.isdigit()]
    multi_hnums = nums[:3]
    return postal, hnum, nums_set, street_words, multi_hnums

def extract_blocking_keys(country, name, raw_addr, clean_a):
    norm_c = norm_country(country)
    cn = clean_name(name)
    keys = []
    if cn:
        keys.append(("N_EXACT", norm_c, cn))
        cr = core_name(cn)
        if cr and cr != cn:
            keys.append(("N_CORE", norm_c, cr))
        words = cn.split()
        if len(words) >= 2:
            keys.append(("N_FIRST2", norm_c, f"{words[0]} {words[1]}"))
            keys.append(("N_SORTED", norm_c, " ".join(sorted(words))))
        nosp = name_no_space(cn)
        if len(nosp) >= 5:
            keys.append(("N_NOSP", norm_c, nosp))

    postal, hnum, nums_set, street_words, multi_hnums = extract_addr_features(raw_addr, clean_a, norm_c)
    for h in multi_hnums:
        if postal and h:
            keys.append(("ZIP_NUM", norm_c, f"{postal}_{h}"))
        if h and street_words:
            keys.append(("NUM_STREET", norm_c, f"{h}_{street_words[0]}"))
        if h and cn:
            w0 = cn.split()[0]
            if len(w0) >= 3:
                keys.append(("NA_NUM", norm_c, f"{h}_{w0}"))
    if clean_a:
        keys.append(("A_EXACT", norm_c, clean_a))
    return keys

def compute_pairwise_features(s1_meta, t_meta):
    s1_cn, s1_ca, s1_cr, s1_nums, s1_hnum, s1_c = s1_meta
    t_cn, t_ca, t_cr, t_nums, t_hnum, t_c = t_meta

    name_exact = 1.0 if (s1_cn and t_cn and s1_cn == t_cn) else 0.0
    name_ratio = 100.0 if name_exact else (fuzz.ratio(s1_cn, t_cn) if (s1_cn and t_cn) else 0.0)
    name_tsr = fuzz.token_set_ratio(s1_cn, t_cn) if (s1_cn and t_cn) else 0.0
    name_tsort = fuzz.token_sort_ratio(s1_cn, t_cn) if (s1_cn and t_cn) else 0.0

    core_exact = 1.0 if (s1_cr and t_cr and s1_cr == t_cr) else 0.0
    core_ratio = fuzz.ratio(s1_cr, t_cr) if (s1_cr and t_cr) else 0.0
    core_tsr = fuzz.token_set_ratio(s1_cr, t_cr) if (s1_cr and t_cr) else 0.0

    addr_tsr = fuzz.token_set_ratio(s1_ca, t_ca) if (s1_ca and t_ca) else 0.0
    num_overlap = 1.0 if (s1_nums and t_nums and (s1_nums & t_nums)) else 0.0

    hnum_match = 1.0 if (s1_hnum and t_hnum and s1_hnum == t_hnum) else 0.0
    hnum_conflict = 1.0 if (s1_hnum and t_hnum and s1_hnum != t_hnum) else 0.0
    country_match = 1.0 if (s1_c and t_c and s1_c == t_c) else 0.0

    return [
        name_ratio, name_tsr, name_tsort, name_exact,
        core_ratio, core_tsr, core_exact,
        addr_tsr, num_overlap, hnum_match, hnum_conflict, country_match
    ]

def main():
    t_total_start = time.time()
    BATCH_SIZE = 500_000

    # Step 1: Load and Index Source 1
    print("\n[Step 1/3] Loading and indexing Source 1 queries...", flush=True)
    t0 = time.time()
    s1_df = pl.read_csv(s1_path, separator="\t")
    n_s1 = len(s1_df)

    s1_eids = s1_df["entity_id"].to_list()
    s1_raw_c = s1_df["country"].to_list()
    s1_raw_nm = s1_df["business_name"].to_list()
    s1_raw_ad = s1_df["business_address"].to_list()
    del s1_df
    gc.collect()

    s1_cc = [norm_country(x) for x in s1_raw_c]
    s1_cn = [clean_name(x) for x in s1_raw_nm]
    s1_ca = [clean_addr(s1_raw_ad[i], s1_cc[i]) for i in range(n_s1)]
    s1_cr = [core_name(x) for x in s1_cn]

    s1_nums, s1_hnums = [], []
    for i in range(n_s1):
        _, hnum, nums_set, _, _ = extract_addr_features(s1_raw_ad[i], s1_ca[i], s1_cc[i])
        s1_nums.append(nums_set)
        s1_hnums.append(hnum)

    s1_lookup = [
        (s1_cn[i], s1_ca[i], s1_cr[i], s1_nums[i], s1_hnums[i], s1_cc[i])
        for i in range(n_s1)
    ]

    index = defaultdict(list)
    for idx in range(n_s1):
        for k in extract_blocking_keys(s1_raw_c[idx], s1_raw_nm[idx], s1_raw_ad[idx], s1_ca[idx]):
            index[k].append(idx)

    max_buckets = {
        "N_EXACT": 100, "N_CORE": 50, "A_EXACT": 100,
        "N_FIRST2": 30, "N_SORTED": 30, "N_NOSP": 40,
        "ZIP_NUM": 30, "NUM_STREET": 25, "NA_NUM": 25,
    }
    for k in list(index.keys()):
        limit = max_buckets.get(k[0], 25)
        if len(index[k]) > limit:
            del index[k]

    print(f"[+] Loaded and indexed {n_s1:,} queries ({len(index):,} active keys) in {time.time()-t0:.1f}s.", flush=True)

    # Step 2: Stream Targets & Score with LightGBM
    print("\n[Step 2/3] Streaming targets & scoring with LightGBM...", flush=True)
    matches_dict = defaultdict(list)
    candidates_dict = defaultdict(list)

    def stream_and_score(path, label):
        t_src = time.time()
        print(f"[*] Processing {label}...", flush=True)
        reader = pl.read_csv_batched(path, separator="\t", batch_size=BATCH_SIZE)
        total_rows = 0
        total_pairs = 0

        while True:
            batches = reader.next_batches(1)
            if not batches:
                break
            b = batches[0]
            total_rows += len(b)
            eids = b["entity_id"].to_list()
            countries = b["country"].to_list()
            names = b["business_name"].to_list()
            addrs = b["business_address"].to_list()
            del b

            batch_s1_indices = []
            batch_t_ids = []
            batch_features = []

            for t_id, c, nm, ad in zip(eids, countries, names, addrs):
                nc = norm_country(c)
                cn = clean_name(nm)
                ca = clean_addr(ad, nc)
                cr = core_name(cn)

                matched_s1 = set()
                if cn:
                    k1 = ("N_EXACT", nc, cn)
                    if k1 in index:
                        matched_s1.update(index[k1])
                    if cr and cr != cn:
                        k2 = ("N_CORE", nc, cr)
                        if k2 in index:
                            matched_s1.update(index[k2])
                _, hnum, nums_set, swords, multi_h = extract_addr_features(ad, ca, nc)
                for h in multi_h:
                    if h and swords:
                        k_ns = ("NUM_STREET", nc, f"{h}_{swords[0]}")
                        if k_ns in index:
                            matched_s1.update(index[k_ns])
                    if h and cn:
                        w0 = cn.split()[0]
                        if len(w0) >= 3:
                            k_na = ("NA_NUM", nc, f"{h}_{w0}")
                            if k_na in index:
                                matched_s1.update(index[k_na])

                if not matched_s1:
                    continue

                t_meta = (cn, ca, cr, nums_set, hnum, nc)
                for s1_idx in matched_s1:
                    feats = compute_pairwise_features(s1_lookup[s1_idx], t_meta)
                    batch_s1_indices.append(s1_idx)
                    batch_t_ids.append(t_id)
                    batch_features.append(feats)

            if batch_features:
                X_batch = np.array(batch_features, dtype=np.float32)
                probs = clf.predict_proba(X_batch)[:, 1]
                total_pairs += len(probs)

                for s1_idx, t_id, prob in zip(batch_s1_indices, batch_t_ids, probs):
                    candidates_dict[s1_idx].append(t_id)
                    if prob >= (TAU - 0.05):
                        matches_dict[s1_idx].append((t_id, float(prob)))

            if total_rows % 1_000_000 == 0:
                print(f"     {label}: {total_rows:,} rows, {total_pairs:,} candidate pairs scored ({time.time()-t_src:.1f}s)", flush=True)

        print(f"[+] {label}: {total_rows:,} rows, {total_pairs:,} candidates scored in {time.time()-t_src:.1f}s.", flush=True)
        gc.collect()

    stream_and_score(s2_path, "Source 2")
    stream_and_score(s3_path, "Source 3")
    del index
    gc.collect()

    # Step 3: Output Generation
    print("\n[Step 3/3] Generating Final Output Files...", flush=True)
    out_dir = "/kaggle/working" if os.path.exists("/kaggle/working") else "output/submmision"
    os.makedirs(out_dir, exist_ok=True)
    match_path = os.path.join(out_dir, "matching_results.tsv")
    cand_path = os.path.join(out_dir, "candidate_pairs.tsv")

    n_with_match = 0
    total_matches = 0

    with open(match_path, "w", encoding="utf-8") as f_match, open(cand_path, "w", encoding="utf-8") as f_cand:
        f_match.write("source1_entity_id\tmatched_entity_ids\n")
        f_cand.write("source1_entity_id\tcandidate_entity_ids\n")

        for idx, eid in enumerate(s1_eids):
            m_list = matches_dict.get(idx, [])
            c_list = candidates_dict.get(idx, [])

            cands = []
            seen_cands = set()
            for cid in c_list:
                if cid not in seen_cands:
                    seen_cands.add(cid)
                    cands.append(cid)
            cands = cands[:15]

            top = []
            if m_list:
                best_prob = max(p for _, p in m_list)
                if best_prob >= TAU:
                    top_candidates = [tid for tid, p in sorted(m_list, key=lambda x: -x[1]) if p >= max(TAU, best_prob - 0.05)][:5]
                    seen_top = set()
                    for tid in top_candidates:
                        if tid not in seen_top:
                            seen_top.add(tid)
                            top.append(tid)

            for tid in top:
                if tid not in seen_cands:
                    seen_cands.add(tid)
                    cands.append(tid)

            if top:
                n_with_match += 1
                total_matches += len(top)
                f_match.write(f"{eid}\t{','.join(top)}\n")
            else:
                f_match.write(f"{eid}\t\n")

            if cands:
                f_cand.write(f"{eid}\t{','.join(cands)}\n")
            else:
                f_cand.write(f"{eid}\t\n")

            if (idx + 1) % 500_000 == 0:
                print(f"     Written {idx+1:,}/{n_s1:,} entities...", flush=True)

    total_time = time.time() - t_total_start
    print("\n" + "=" * 80)
    print(f"[✔] Pipeline Completed Successfully in {total_time:.1f}s ({total_time/60:.1f} min)")
    print(f"    Saved Matching   : {match_path} ({os.path.getsize(match_path)/(1024*1024):.2f} MB)")
    print(f"    Saved Candidates : {cand_path} ({os.path.getsize(cand_path)/(1024*1024):.2f} MB)")
    print(f"    Entities Matched : {n_with_match:,} / {n_s1:,} ({n_with_match/n_s1*100:.1f}%)")
    print(f"    Singletons       : {n_s1 - n_with_match:,} ({(n_s1 - n_with_match)/n_s1*100:.1f}%)")
    print(f"    Total Matches    : {total_matches:,}")
    print("=" * 80, flush=True)

if __name__ == "__main__":
    main()
